+    for (unsigned s=0; s < flow->mod_comp_params.num_sections; s++) {
+        if (flow->mod_comp_params.sections[s].section_id == sectionId) {
+            return &flow->mod_comp_params.sections[s];
+        }
+    }
+
+    /* Not found */
+    return NULL;
+}
